var n=`0699-fufu-with-peanut-sauce`;var i=`world-0699`;var a=`TG`;var o=`western-africa`;var s=4;var r=79;var u={en:`Fufu with Peanut Sauce`,ua:`Фуфу з арахісовим соусом`};var l={en:`Fufu with Peanut Sauce is a Togo classic prepared with yam, plantain, yellow onion, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Фуфу з арахісовим соусом, страва кухні країни Того зі складниками: ямс, плантан, жовта цибуля, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 30 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 30 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:30,i:[[`yam`,700,`g`],[`plantain`,350,`g`],[`water`,1100,`ml`]]},{en:`Drain the cooked ingredients and pound or mash while warm for about 14 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 14 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:14,i:[]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,160,`g`],[`tomato`,310,`g`],[`peanut-oil`,35,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`peanut-butter`,220,`g`],[`water`,530,`ml`],[`scotch-bonnet-pepper`,1,`pcs`]]}];var m={slug:n,id:i,country:`TG`,region:o,servings:4,minutes:79,title:u,text:l,steps:d};export{a as country,m as default,i as id,r as minutes,o as region,s as servings,n as slug,d as steps,l as text,u as title};